export const termuxStartScript = "#!/data/data/com.termux/files/usr/bin/bash\n# 开启后台唤醒锁防止休眠\ntermux-wake-lock\n\necho \"🚀 正在更新环境及安装 Python 与依赖...\"\npkg update -y && pkg install -y python git\npip install --upgrade pip\npip install pyTelegramBotAPI requests urllib3\n\necho \"✅ 准备启动澳门三分六合彩预测机器人...\"\nif [ ! -f config.json ]; then\n    echo \"⚠️ 未发现 config.json，将自动生成默认模板...\"\nfi\n\npython bot.py\n";
